import { inBrowser, onContentUpdated } from "vitepress";
//#region src/client/app/composables/codeGroups.ts
function useCodeGroups() {
	if (import.meta.env.DEV) onContentUpdated(() => {
		document.querySelectorAll(".vp-code-group > .blocks").forEach((el) => {
			Array.from(el.children).forEach((child) => {
				child.classList.remove("active");
			});
			const first = el.children[0];
			if (first) activate(first);
		});
	});
	if (inBrowser) window.addEventListener("click", (e) => {
		const el = e.target;
		if (el.matches(".vp-code-group input")) {
			const group = el.parentElement?.parentElement;
			if (!group) return;
			const i = Array.from(group.querySelectorAll("input")).indexOf(el);
			if (i < 0) return;
			const blocks = group.querySelector(".blocks");
			if (!blocks) return;
			const current = Array.from(blocks.children).find((child) => child.classList.contains("active"));
			if (!current) return;
			const next = blocks.children[i];
			if (!next || current === next) return;
			current.classList.remove("active");
			activate(next);
			(group?.querySelector(`label[for="${el.id}"]`))?.scrollIntoView({ block: "nearest" });
		}
	});
}
function activate(el) {
	el.classList.add("active");
	window.dispatchEvent(new CustomEvent("vitepress:codeGroupTabActivate", { detail: el }));
}
//#endregion
export { useCodeGroups };
